import copy


def _merge(base, patch):
    out = copy.deepcopy(base)
    for key, value in patch.items():
        if value is None:
            out.pop(key, None)
        elif isinstance(value, dict) and isinstance(out.get(key), dict):
            out[key] = _merge(out[key], value)
        else:
            out[key] = copy.deepcopy(value)
    return out


def _matches(trace, selector):
    if selector is None:
        return True
    return all(key in trace and trace[key] == value
               for key, value in selector.items())


def update(spec, layout=None, traces=None, selector=None):
    if not isinstance(spec, dict) or "data" not in spec or "layout" not in spec:
        raise ValueError("a figure spec needs both 'data' and 'layout'")
    if not isinstance(spec["data"], list):
        raise ValueError("'data' must be a list of traces")
    new_layout = _merge(spec["layout"], layout or {})
    new_data = []
    for trace in spec["data"]:
        if traces is not None and _matches(trace, selector):
            new_data.append(_merge(trace, traces))
        else:
            new_data.append(copy.deepcopy(trace))
    return {"data": new_data, "layout": new_layout}
